import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.Cp9o0o35.js";const m=JSON.parse('{"title":"三種の比較","description":"","frontmatter":{},"headers":[],"relativePath":"ja/compare.md","filePath":"ja/compare.md"}'),i={name:"ja/compare.md"};function s(n,a,l,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="三種の比較" tabindex="-1">三種の比較 <a class="header-anchor" href="#三種の比較" aria-label="Permalink to &quot;三種の比較&quot;">​</a></h1><p>bridge-lite は「撮って出し（JPEG）」「RAW」「現像済み」を<strong>1つのグループ</strong>として扱います。</p><h2 id="なぜ三種を並べるのか" tabindex="-1">なぜ三種を並べるのか <a class="header-anchor" href="#なぜ三種を並べるのか" aria-label="Permalink to &quot;なぜ三種を並べるのか&quot;">​</a></h2><p>現像によって思い通りの色が出せることもあれば、カメラ出力の方が素直に良い場合もあります。また、現像を重ねるうちに元の色調を見失うこともあります。三つを行き来することで、判断の根拠を確かめながらセレクトができます。</p><h2 id="グループの切り替え" tabindex="-1">グループの切り替え <a class="header-anchor" href="#グループの切り替え" aria-label="Permalink to &quot;グループの切り替え&quot;">​</a></h2><p>サムネイルを選択した状態で <code>Tab</code> キーを押すと、同じシャッターから生まれたファイルを順番に切り替えます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>撮って出し（JPEG） → RAW → 現像済み → 撮って出し → …</span></span></code></pre></div><h2 id="ペアリングの仕組み" tabindex="-1">ペアリングの仕組み <a class="header-anchor" href="#ペアリングの仕組み" aria-label="Permalink to &quot;ペアリングの仕組み&quot;">​</a></h2><p>RAW と JPG の自動ペアリングは以下の順で行われます。</p><ol><li><strong>ステム名</strong> — <code>DSC04867.ARW</code> と <code>DSC04867.JPG</code> のようにファイル名（拡張子を除く部分）が一致するもの</li><li><strong>EXIF タイムスタンプ</strong> — ステム名が異なっても撮影時刻が一致するもの</li><li><strong>pHash</strong> — 知覚ハッシュによる視覚的類似度</li></ol><h2 id="グループ比較ビュー" tabindex="-1">グループ比較ビュー <a class="header-anchor" href="#グループ比較ビュー" aria-label="Permalink to &quot;グループ比較ビュー&quot;">​</a></h2><p><code>G</code> キーでグループ比較ビューを開くと、三種を画面上に並べて表示できます。</p><h2 id="現像バリアントとは" tabindex="-1">現像バリアントとは <a class="header-anchor" href="#現像バリアントとは" aria-label="Permalink to &quot;現像バリアントとは&quot;">​</a></h2><p>Lightroom などで書き出した JPEG や TIFF が、同じステム名で同じフォルダに存在する場合、bridge-lite はそれを「現像済み」バリアントとして自動的に認識します。</p>',14)])])}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
